// Metricas del embudo a partir de las columnas de la planilla:
//   estado, fecha_postulacion  -> postulaciones y entrevistas
//   fecha_deteccion            -> ofertas nuevas de la semana
//   match_pct                  -> calidad del match (0 o vacio = sin evaluar)
//   hv_adaptada, hv_pdf        -> HV generadas
//   fuente                     -> portal de origen
const rows = $input.all().map(i => i.json);
const UMBRAL_MATCH = 83;
const FUENTES = ['LinkedIn', 'Computrabajo', 'Elempleo', 'Magneto365'];

const norm = (s) => String(s ?? '').trim().toLowerCase();
const lleno = (v) => String(v ?? '').trim() !== '';

// Postulada: fecha_postulacion con dato, o un estado posterior a postularse.
// "Pendiente", "Descartado" y vacio no cuentan.
const ESTADOS_SIN_POSTULAR = ['', 'pendiente', 'descartado', 'descartada'];
const postulada = (r) => lleno(r.fecha_postulacion) || !ESTADOS_SIN_POSTULAR.includes(norm(r.estado));
const enEntrevista = (r) => norm(r.estado).includes('entrevista');

const match = (r) => {
  const n = Number(String(r.match_pct ?? '').replace(',', '.'));
  return Number.isFinite(n) && n > 0 ? n : null;
};

// Fechas de la planilla: "2026-10-23 10:05", "2026-10-23", "23/10/2026" o numero de serie de Sheets
const fecha = (v) => {
  const s = String(v ?? '').trim();
  if (!s) return null;
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return new Date(+m[1], +m[2] - 1, +m[3]);
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return new Date(+m[3], +m[2] - 1, +m[1]);
  if (/^\d+(\.\d+)?$/.test(s)) return new Date(Date.UTC(1899, 11, 30) + Number(s) * 86400000);
  return null;
};
const haceUnaSemana = new Date(Date.now() - 7 * 86400000);
const estaSemana = (v) => { const f = fecha(v); return !!f && f >= haceUnaSemana; };

const pct = (num, den) => (den > 0 ? Math.round((num / den) * 1000) / 10 : null);
const promedio = (lista) => {
  const vals = lista.map(match).filter((n) => n !== null);
  return vals.length ? Math.round((vals.reduce((a, b) => a + b, 0) / vals.length) * 10) / 10 : null;
};

const estados = {};
for (const r of rows) {
  const e = String(r.estado ?? '').trim() || '(vacio)';
  estados[e] = (estados[e] || 0) + 1;
}

const postuladas = rows.filter(postulada);
const entrevistas = rows.filter(enEntrevista);
const altoMatch = rows.filter((r) => (match(r) ?? 0) >= UMBRAL_MATCH);
const sinMatch = rows.filter((r) => match(r) === null);
const conHv = rows.filter((r) => lleno(r.hv_adaptada));
const postuladasConHv = postuladas.filter((r) => lleno(r.hv_adaptada));
const postuladasSinHv = postuladas.filter((r) => !lleno(r.hv_adaptada));
const pendientes = rows.filter((r) => !postulada(r) && !ESTADOS_SIN_POSTULAR.slice(2).includes(norm(r.estado)));

const porFuente = {};
for (const f of FUENTES) porFuente[f] = { total: 0, postuladas: 0 };
for (const r of rows) {
  const f = String(r.fuente ?? '').trim() || 'sin fuente';
  porFuente[f] = porFuente[f] || { total: 0, postuladas: 0 };
  porFuente[f].total++;
  if (postulada(r)) porFuente[f].postuladas++;
}

return [{
  json: {
    umbral: UMBRAL_MATCH,
    total: rows.length,
    estados,
    semana: {
      nuevas: rows.filter((r) => estaSemana(r.fecha_deteccion)).length,
      postuladas: rows.filter((r) => estaSemana(r.fecha_postulacion)).length,
    },
    postuladas: postuladas.length,
    conFechaPostulacion: rows.filter((r) => lleno(r.fecha_postulacion)).length,
    entrevistas: entrevistas.length,
    tasaEntrevista: pct(entrevistas.length, postuladas.length),
    altoMatch: altoMatch.length,
    altoMatchPostuladas: altoMatch.filter(postulada).length,
    tasaAltoMatchPostulacion: pct(altoMatch.filter(postulada).length, altoMatch.length),
    sinMatch: sinMatch.length,
    promedioMatch: promedio(rows),
    promedioMatchPostuladas: promedio(postuladas),
    promedioMatchEntrevista: promedio(entrevistas),
    conHv: conHv.length,
    conPdf: rows.filter((r) => lleno(r.hv_pdf)).length,
    postuladasSinPdf: postuladas.filter((r) => !lleno(r.hv_pdf)).length,
    postuladasConHv: postuladasConHv.length,
    postuladasSinHv: postuladasSinHv.length,
    tasaEntrevistaConHv: pct(postuladasConHv.filter(enEntrevista).length, postuladasConHv.length),
    tasaEntrevistaSinHv: pct(postuladasSinHv.filter(enEntrevista).length, postuladasSinHv.length),
    pendientes: pendientes.length,
    pendientesAltoMatch: pendientes.filter((r) => (match(r) ?? 0) >= UMBRAL_MATCH).length,
    porFuente,
  },
}];

// Cada linea dice de que columna de la planilla sale el dato. Los nombres de columna van
// como codigo: en Markdown de Telegram un "_" suelto rompe el mensaje.
const m = $input.first().json;
const p = (v) => (v === null || v === undefined ? 'sin datos todavia' : `${v}%`);
const col = (nombre) => '`' + nombre + '`';

let t = `📊 *Metricas semanales — busqueda laboral*\n\n`;

t += `*Esta semana* (ultimos 7 dias)\n`;
t += `Ofertas nuevas (${col('fecha_deteccion')}): ${m.semana.nuevas}\n`;
t += `Te postulaste (${col('fecha_postulacion')}): ${m.semana.postuladas}\n\n`;

t += `*En la planilla* (${m.total} filas)\n`;
t += `Columna ${col('estado')}: ${Object.entries(m.estados).map(([e, n]) => `${e} ${n}`).join(' · ')}\n`;
t += `Postuladas: ${m.postuladas} (${col('estado')} distinto de Pendiente o Descartado, o con ${col('fecha_postulacion')})\n`;
if (m.pendientes) {
  t += `Por postular (Pendiente): ${m.pendientes}, ${m.pendientesAltoMatch} con match ≥ ${m.umbral}%\n`;
}
t += `\n`;

t += `*Embudo*\n`;
t += `Match ≥ ${m.umbral}% (${col('match_pct')}): ${m.altoMatch} → te postulaste a ${m.altoMatchPostuladas} (${p(m.tasaAltoMatchPostulacion)})\n`;
t += `Postuladas → entrevista (${col('estado')} = Entrevista): ${m.entrevistas} de ${m.postuladas} (${p(m.tasaEntrevista)})\n\n`;

t += `*¿El match predice bien?* (${col('match_pct')}`;
t += m.sinMatch ? `; ${m.sinMatch} fila(s) en 0 o vacias no cuentan)\n` : `)\n`;
t += `Promedio de todas: ${p(m.promedioMatch)}\n`;
t += `Promedio de las postuladas: ${p(m.promedioMatchPostuladas)}\n`;
t += `Promedio de las que llegaron a entrevista: ${p(m.promedioMatchEntrevista)}\n\n`;

t += `*HV adaptada*\n`;
t += `Con Google Doc (${col('hv_adaptada')}): ${m.conHv} · con PDF (${col('hv_pdf')}): ${m.conPdf}\n`;
if (m.postuladasSinPdf) t += `Postuladas sin PDF: ${m.postuladasSinPdf}\n`;
if (m.postuladasSinHv === 0) {
  t += `Todas las postuladas tienen HV adaptada: aun no hay con que comparar si ayuda\n`;
} else {
  t += `Entrevista con HV adaptada: ${p(m.tasaEntrevistaConHv)} de ${m.postuladasConHv}\n`;
  t += `Entrevista sin HV adaptada: ${p(m.tasaEntrevistaSinHv)} de ${m.postuladasSinHv}\n`;
}
t += `\n`;

t += `*Por fuente* (${col('fuente')})\n`;
for (const [fuente, d] of Object.entries(m.porFuente)) {
  t += `${fuente}: ${d.total} en la planilla, ${d.postuladas} postuladas\n`;
}

return [{ json: { texto: t.trim() } }];
